import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.mrTIYZc5.js";const p=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"guide/privacy.md","filePath":"guide/privacy.md"}'),o={name:"guide/privacy.md"};function l(s,e,n,c,d,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy Policy&quot;">​</a></h1><p><strong>Last Updated</strong>: May 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Docker Secret Operator (DSO) is an open-source project committed to user privacy. This privacy policy explains how data is handled when you use DSO and interact with the DSO website and documentation.</p><h2 id="data-collection" tabindex="-1">Data Collection <a class="header-anchor" href="#data-collection" aria-label="Permalink to &quot;Data Collection&quot;">​</a></h2><h3 id="what-we-collect" tabindex="-1">What We Collect <a class="header-anchor" href="#what-we-collect" aria-label="Permalink to &quot;What We Collect&quot;">​</a></h3><ul><li><strong>Usage Analytics</strong>: Non-identifying usage statistics collected via Vercel Analytics (page views, referrers, device type)</li><li><strong>Newsletter Signups</strong>: Email addresses provided voluntarily through the newsletter signup form</li><li><strong>Error Logs</strong>: Server-side error logs (no personal data included)</li></ul><h3 id="what-we-don-t-collect" tabindex="-1">What We Don&#39;t Collect <a class="header-anchor" href="#what-we-don-t-collect" aria-label="Permalink to &quot;What We Don&#39;t Collect&quot;">​</a></h3><ul><li><strong>No User Tracking</strong>: DSO does not include telemetry or tracking in the operator binary itself</li><li><strong>No Behavioral Profiling</strong>: We do not profile user behavior beyond basic analytics</li><li><strong>No Third-Party Cookies</strong>: We do not use third-party tracking or advertising cookies</li><li><strong>No Device Fingerprinting</strong>: We do not fingerprint or track devices</li></ul><h2 id="data-usage" tabindex="-1">Data Usage <a class="header-anchor" href="#data-usage" aria-label="Permalink to &quot;Data Usage&quot;">​</a></h2><h3 id="newsletter-emails" tabindex="-1">Newsletter Emails <a class="header-anchor" href="#newsletter-emails" aria-label="Permalink to &quot;Newsletter Emails&quot;">​</a></h3><p>Emails collected through the newsletter signup form are used solely to:</p><ul><li>Send welcome messages</li><li>Provide updates on DSO releases and security advisories</li><li>Share architectural deep-dives and best practices</li></ul><p>You can unsubscribe at any time by replying with &quot;unsubscribe&quot; or clicking an unsubscribe link in emails.</p><h3 id="analytics-data" tabindex="-1">Analytics Data <a class="header-anchor" href="#analytics-data" aria-label="Permalink to &quot;Analytics Data&quot;">​</a></h3><p>Analytics data helps us understand:</p><ul><li>Popular documentation pages</li><li>Traffic sources</li><li>Device and browser compatibility</li><li>Geographic distribution (country-level only)</li></ul><p>This data is aggregated and anonymized.</p><h2 id="data-storage-security" tabindex="-1">Data Storage &amp; Security <a class="header-anchor" href="#data-storage-security" aria-label="Permalink to &quot;Data Storage &amp; Security&quot;">​</a></h2><ul><li><strong>Email Storage</strong>: Emails are stored securely with Gmail&#39;s infrastructure</li><li><strong>Analytics</strong>: Data is stored on Vercel&#39;s infrastructure with industry-standard encryption</li><li><strong>Retention</strong>: Email lists are retained indefinitely unless you request deletion; analytics data follows Vercel&#39;s default retention policy</li><li><strong>Encryption in Transit</strong>: All data transmission uses HTTPS/TLS encryption</li></ul><h2 id="the-dso-operator-binary" tabindex="-1">The DSO Operator Binary <a class="header-anchor" href="#the-dso-operator-binary" aria-label="Permalink to &quot;The DSO Operator Binary&quot;">​</a></h2><p>The DSO operator (the actual Docker plugin) does not collect any data:</p><ul><li>No telemetry is sent to any server</li><li>No usage statistics are reported</li><li>No environment data is logged remotely</li><li>All operations are local to your Docker host</li></ul><h2 id="third-party-services" tabindex="-1">Third-Party Services <a class="header-anchor" href="#third-party-services" aria-label="Permalink to &quot;Third-Party Services&quot;">​</a></h2><p>We use the following services:</p><table tabindex="0"><thead><tr><th>Service</th><th>Purpose</th><th>Data Shared</th><th>Privacy Link</th></tr></thead><tbody><tr><td>Vercel</td><td>Hosting &amp; Analytics</td><td>Page views, referrers, device type</td><td><a href="https://vercel.com/privacy" target="_blank" rel="noreferrer">vercel.com/privacy</a></td></tr><tr><td>Gmail</td><td>Newsletter delivery</td><td>Email addresses</td><td><a href="https://google.com/policies/privacy" target="_blank" rel="noreferrer">google.com/policies/privacy</a></td></tr><tr><td>GitHub</td><td>Code hosting</td><td>Public repository data</td><td><a href="https://github.com/privacy" target="_blank" rel="noreferrer">github.com/privacy</a></td></tr></tbody></table><h2 id="your-rights" tabindex="-1">Your Rights <a class="header-anchor" href="#your-rights" aria-label="Permalink to &quot;Your Rights&quot;">​</a></h2><p>Depending on your location, you may have rights to:</p><ul><li><strong>Access</strong>: Request a copy of your data</li><li><strong>Deletion</strong>: Request deletion of your email from our newsletter</li><li><strong>Correction</strong>: Request correction of inaccurate data</li><li><strong>Portability</strong>: Request your data in a portable format</li></ul><p>To exercise these rights, email <code>umairmd385@gmail.com</code> with &quot;Privacy Request&quot; in the subject line.</p><h2 id="gdpr-privacy-laws" tabindex="-1">GDPR &amp; Privacy Laws <a class="header-anchor" href="#gdpr-privacy-laws" aria-label="Permalink to &quot;GDPR &amp; Privacy Laws&quot;">​</a></h2><p>For users in the EU (GDPR), UK (UKPDC), or other jurisdictions with privacy regulations:</p><ul><li>We collect personal data only with your consent (newsletter signup)</li><li>We process data only for stated purposes</li><li>We retain data only as long as necessary</li><li>We respect your right to withdraw consent</li><li>We maintain a Data Processing Agreement with Vercel</li></ul><p>If you have concerns about our privacy practices, you may lodge a complaint with your local data protection authority.</p><h2 id="changes-to-this-policy" tabindex="-1">Changes to This Policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to &quot;Changes to This Policy&quot;">​</a></h2><p>We may update this privacy policy periodically. Changes will be posted here with an updated &quot;Last Updated&quot; date. Continued use of DSO after changes constitutes acceptance of the updated policy.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>For privacy inquiries or concerns:</p><ul><li><strong>Email</strong>: <code>umairmd385@gmail.com</code></li><li><strong>Subject</strong>: &quot;Privacy Inquiry&quot;</li><li><strong>GitHub</strong>: <a href="https://github.com/docker-secret-operator/dso" target="_blank" rel="noreferrer">docker-secret-operator/dso</a></li></ul><h2 id="open-source-transparency" tabindex="-1">Open Source Transparency <a class="header-anchor" href="#open-source-transparency" aria-label="Permalink to &quot;Open Source Transparency&quot;">​</a></h2><p>DSO is fully open-source under the Apache-2.0 license. You can review exactly what data is collected and how by inspecting:</p><ul><li>Frontend source code: <a href="https://github.com/docker-secret-operator/dso" target="_blank" rel="noreferrer">github.com/docker-secret-operator/dso</a></li><li>This documentation is part of the public repository</li></ul><hr><p><strong>Remember</strong>: DSO is a security-first tool. Your secrets never leave your Docker host. Your privacy is fundamental to that commitment.</p>',44)])])}const y=t(o,[["render",l]]);export{p as __pageData,y as default};
